alter table public.home_sections drop constraint home_sections_kind_check;
alter table public.home_sections add constraint home_sections_kind_check check(kind in ('technical_search','hero','slider','benefits','catalog','academy','statistics','rich_text','brands','contact','campaigns'));
create table private.member_profiles(user_id uuid primary key references auth.users(id) on delete cascade,name text not null default '' check(length(name)<=160),company text not null default '' check(length(company)<=240),phone text not null default '' check(length(phone)<=40),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table private.member_profiles enable row level security;
revoke all on private.member_profiles from public,anon,authenticated;
grant all on private.member_profiles to service_role;
alter table private.quotes add column member_id uuid references auth.users(id) on delete set null;
create index quotes_member on private.quotes(member_id,created_at desc);
create function public.my_account(p_profile jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 if auth.uid() is null then raise exception 'Üye girişi gerekli.' using errcode='42501';end if;
 if p_profile is not null then
 if jsonb_typeof(p_profile)<>'object' or pg_column_size(p_profile)>8192 then raise exception 'Profil verisi geçersiz.' using errcode='22023';end if;
 insert into private.member_profiles(user_id,name,company,phone) values(auth.uid(),coalesce(p_profile->>'name',''),coalesce(p_profile->>'company',''),coalesce(p_profile->>'phone','')) on conflict(user_id) do update set name=excluded.name,company=excluded.company,phone=excluded.phone,updated_at=now();end if;
 select jsonb_build_object('profile',coalesce((select to_jsonb(p)-'user_id' from private.member_profiles p where user_id=auth.uid()),'{}'),'quotes',coalesce((select jsonb_agg(t) from (select q.id,q.status,q.created_at,q.response_note,jsonb_array_length(coalesce((select jsonb_agg(i.id) from private.quote_items i where i.quote_id=q.id),'[]')) lines from private.quotes q where q.member_id=auth.uid() order by q.created_at desc limit 50)t),'[]')) into result;return result;end $$;
revoke all on function public.my_account(jsonb) from public,anon;grant execute on function public.my_account(jsonb) to authenticated;

create table public.campaigns(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id),title text not null default '' check(length(title)<=240),starts_at timestamptz,ends_at timestamptz,sort_order int not null default 0,status public.publication_state not null default 'draft',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),lock_version int not null default 1,check(ends_at is null or starts_at is null or ends_at>starts_at));
create index campaigns_active on public.campaigns(status,sort_order,id) where deleted_at is null;
create unique index campaigns_one_active_product on public.campaigns(product_id) where deleted_at is null;
create table private.campaign_prices(campaign_id uuid primary key references public.campaigns(id) on delete cascade,amount numeric(18,4) not null check(amount>=0),currency text not null default 'TRY' check(currency ~ '^[A-Z]{3}$'));
alter table public.campaigns enable row level security;alter table private.campaign_prices enable row level security;
revoke all on public.campaigns,private.campaign_prices from public,anon,authenticated;
grant select on public.campaigns to anon,authenticated;grant all on public.campaigns,private.campaign_prices to service_role;
create policy campaign_read on public.campaigns for select to anon,authenticated using(status='published' and deleted_at is null and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now()) and private.product_is_public(product_id));
create trigger campaign_touch before update on public.campaigns for each row execute function private.touch_row();
create trigger campaign_audit after insert or update or delete on public.campaigns for each row execute function private.record_change();
create trigger campaign_revision after insert or update or delete on public.campaigns for each statement execute function private.bump_content_version();
create function public.admin_campaigns(p_page int default 1,p_query text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform private.require_admin();if p_page not between 1 and 100000 or length(p_query)>240 then raise exception 'Geçersiz kampanya sorgusu.' using errcode='22023';end if;
 return(with filtered as(select c.*,p.sku,p.name,cp.amount,cp.currency from public.campaigns c join public.products p on p.id=c.product_id left join private.campaign_prices cp on cp.campaign_id=c.id where c.deleted_at is null and (p_query='' or strpos(lower(c.title||' '||p.sku||' '||p.name),lower(p_query))>0)),chosen as(select * from filtered order by sort_order,id limit 50 offset(p_page-1)*50) select jsonb_build_object('total',(select count(*) from filtered),'items',coalesce((select jsonb_agg(to_jsonb(c)) from chosen c),'[]')));end $$;
create function public.admin_save_campaign(p_id uuid,p_version int,p_data jsonb,p_delete boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare old public.campaigns;c public.campaigns;new_id uuid:=coalesce(p_id,gen_random_uuid());result jsonb;begin perform private.require_admin();
 if p_id is not null then select * into old from public.campaigns where id=p_id and deleted_at is null for update;if not found then raise exception 'Kampanya yok.' using errcode='P0002';end if;if old.lock_version is distinct from p_version then raise exception 'Kampanya değişti. Yenileyin.' using errcode='PT409';end if;end if;
 if p_delete then update public.campaigns set deleted_at=now(),status='draft' where id=p_id returning to_jsonb(campaigns.*) into result;return result;end if;
 if jsonb_typeof(p_data)<>'object' or pg_column_size(p_data)>8192 then raise exception 'Kampanya verisi geçersiz.' using errcode='22023';end if;
 c:=jsonb_populate_record(null::public.campaigns,'{"title":"","status":"draft","sort_order":0}'::jsonb||coalesce(to_jsonb(old),'{}')||p_data);
 if not exists(select 1 from public.products where id=c.product_id and deleted_at is null and (c.status='draft' or private.product_is_public(id))) then raise exception 'Yayında kampanya için ürün de yayında olmalıdır.' using errcode='22023';end if;
 if nullif(p_data->>'amount','') is null then raise exception 'Üyelere özel kampanya fiyatını girin.' using errcode='22023';end if;
 if p_id is null then insert into public.campaigns(id,product_id,title,starts_at,ends_at,sort_order,status) values(new_id,c.product_id,c.title,c.starts_at,c.ends_at,c.sort_order,c.status) returning to_jsonb(campaigns.*) into result;
 else update public.campaigns set product_id=c.product_id,title=c.title,starts_at=c.starts_at,ends_at=c.ends_at,sort_order=c.sort_order,status=c.status where id=p_id returning to_jsonb(campaigns.*) into result;end if;
 insert into private.campaign_prices(campaign_id,amount,currency) values(new_id,(p_data->>'amount')::numeric,coalesce(p_data->>'currency','TRY')) on conflict(campaign_id) do update set amount=excluded.amount,currency=excluded.currency;return result;end $$;
create function public.get_public_campaigns(p_page int default 1,p_size int default 12) returns jsonb language plpgsql stable security definer set search_path='' as $$begin if p_page not between 1 and 100000 or p_size not between 1 and 50 then raise exception 'Geçersiz sayfa.' using errcode='22023';end if;
 return(with active as(select * from public.campaigns c where status='published' and deleted_at is null and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now()) and private.product_is_public(product_id)),chosen as(select * from active order by sort_order,id limit p_size offset(p_page-1)*p_size) select jsonb_build_object('total',(select count(*) from active),'items',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'starts_at',c.starts_at,'ends_at',c.ends_at,'product',private.public_product_card(p)-'price') order by c.sort_order,c.id) from chosen c join public.products p on p.id=c.product_id),'[]')));end $$;
create function public.get_member_campaign_prices(p_ids uuid[]) returns jsonb language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Fiyatlar için üye girişi gerekli.' using errcode='42501';end if;if cardinality(p_ids)>100 then raise exception 'En fazla 100 fiyat sorgulanabilir.' using errcode='22023';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('campaign_id',c.id,'amount',p.amount,'currency',p.currency)) from public.campaigns c join private.campaign_prices p on p.campaign_id=c.id where c.id=any(p_ids) and c.status='published' and c.deleted_at is null and (c.starts_at is null or c.starts_at<=now()) and (c.ends_at is null or c.ends_at>now()) and private.product_is_public(c.product_id)),'[]');end $$;
revoke all on function public.admin_campaigns(int,text),public.admin_save_campaign(uuid,int,jsonb,boolean),public.get_member_campaign_prices(uuid[]) from public,anon;
grant execute on function public.admin_campaigns(int,text),public.admin_save_campaign(uuid,int,jsonb,boolean),public.get_member_campaign_prices(uuid[]) to authenticated;
grant execute on function public.get_public_campaigns(int,int) to anon,authenticated;

create table private.site_events(id uuid primary key,occurred_at timestamptz not null default now(),session_hash text not null check(session_hash ~ '^[0-9a-f]{64}$'),ip_hash text not null check(ip_hash ~ '^[0-9a-f]{64}$'),ip_mask text not null check(length(ip_mask)<=80),country text check(length(country)<=2),region text check(length(region)<=120),city text check(length(city)<=120),kind text not null check(kind in ('page_view','product_view')),path text not null check(length(path)<=500),product_id text check(length(product_id)<=160),product_name text check(length(product_name)<=500),referrer_host text check(length(referrer_host)<=200),device text not null check(device in ('mobile','desktop','tablet','unknown')));
create index site_events_time on private.site_events(occurred_at desc,id);create index site_events_session on private.site_events(session_hash,occurred_at);create index site_events_product on private.site_events(product_id,occurred_at) where kind='product_view';
create table private.site_rate_limits(scope text not null,key_hash text not null check(key_hash ~ '^[0-9a-f]{64}$'),window_start timestamptz not null,attempts int not null,primary key(scope,key_hash,window_start));
alter table private.site_events enable row level security;alter table private.site_rate_limits enable row level security;
revoke all on private.site_events,private.site_rate_limits from public,anon,authenticated;grant all on private.site_events,private.site_rate_limits to service_role;
create function private.consume_site_limit(p_scope text,p_hash text,p_limit int) returns boolean language plpgsql security definer set search_path='' as $$declare n int;begin
 insert into private.site_rate_limits values(p_scope,p_hash,date_trunc('minute',clock_timestamp()),1) on conflict(scope,key_hash,window_start) do update set attempts=site_rate_limits.attempts+1 returning attempts into n;return n<=p_limit;end $$;
revoke all on function private.consume_site_limit(text,text,int) from public,anon,authenticated;
create function public.ingest_site_event(p_data jsonb) returns boolean language plpgsql security definer set search_path='' as $$begin
 if coalesce((select (value->>'enabled')::boolean from public.site_settings where key='analytics'),false) is not true or (p_data->>'consent') is distinct from 'true' then return false;end if;
 if not private.consume_site_limit('analytics',p_data->>'ip_hash',120) then return false;end if;
 insert into private.site_events(id,session_hash,ip_hash,ip_mask,country,region,city,kind,path,product_id,product_name,referrer_host,device) values((p_data->>'id')::uuid,p_data->>'session_hash',p_data->>'ip_hash',p_data->>'ip_mask',nullif(p_data->>'country',''),p_data->>'region',p_data->>'city',p_data->>'kind',p_data->>'path',p_data->>'product_id',p_data->>'product_name',p_data->>'referrer_host',p_data->>'device') on conflict(id) do nothing;
 delete from private.site_events where id in(select id from private.site_events where occurred_at<now()-interval '90 days' limit 5000);delete from private.site_rate_limits where window_start<now()-interval '1 day';return true;end $$;
revoke all on function public.ingest_site_event(jsonb) from public,anon,authenticated;grant execute on function public.ingest_site_event(jsonb) to service_role;
create function public.admin_analytics(p_filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare from_time timestamptz:=coalesce(nullif(p_filters->>'from','')::timestamptz,now()-interval '7 days');until_time timestamptz:=coalesce(nullif(p_filters->>'to','')::timestamptz+interval '1 day',clock_timestamp());page_no int:=coalesce((p_filters->>'page')::int,1);begin perform private.require_admin();
 if page_no not between 1 and 100000 or until_time<from_time or until_time-from_time>interval '180 days' then raise exception 'Tarih aralığı geçersiz (en fazla 180 gün).' using errcode='22023';end if;
 return(with events as materialized(select * from private.site_events where occurred_at>=from_time and occurred_at<until_time),filtered as(select * from events where (coalesce(p_filters->>'session','')='' or session_hash=p_filters->>'session') and (coalesce(p_filters->>'country','')='' or country=p_filters->>'country')),chosen as(select * from filtered order by occurred_at desc,id limit 50 offset(page_no-1)*50)
 select jsonb_build_object('sessions',(select count(distinct session_hash) from events),'views',(select count(*) from events where kind='page_view'),'productViews',(select count(*) from events where kind='product_view'),'total',(select count(*) from filtered),'items',coalesce((select jsonb_agg(to_jsonb(c)-'ip_hash') from chosen c),'[]'),'locations',coalesce((select jsonb_agg(t) from(select country,city,count(distinct session_hash) visits from events group by country,city order by visits desc limit 20)t),'[]'),'products',coalesce((select jsonb_agg(t) from(select product_id,max(product_name) name,count(*) views from events where kind='product_view' group by product_id order by views desc limit 20)t),'[]')));end $$;
revoke all on function public.admin_analytics(jsonb) from public,anon;grant execute on function public.admin_analytics(jsonb) to authenticated;

create function public.submit_site_quote(p_data jsonb,p_ip_hash text,p_fingerprint text,p_member_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare prior private.quotes;customer_id_value uuid;quote_id uuid;v jsonb;p public.products;details jsonb:=p_data->'details';customer_name text:=trim(coalesce(details->>'customer',details->>'name',''));email_value text:=lower(trim(details->>'email'));company_value text:=trim(coalesce(details->>'company',''));n int:=0;begin
 if pg_column_size(p_data)>131072 or length(customer_name) not between 1 and 160 or email_value is null or email_value!~'^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' or length(email_value)>254 or length(details->>'phone')>40 or length(details->>'note')>1200 or jsonb_typeof(p_data->'items') is distinct from 'array' or jsonb_array_length(p_data->'items')>100 or coalesce(p_data->>'website','')<>'' then raise exception 'Teklif formunu kontrol edin.' using errcode='22023';end if;
 if jsonb_array_length(p_data->'items')=0 and length(trim(coalesce(details->>'note','')))=0 then raise exception 'Ürün seçin veya talebinizi yazın.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_data->>'requestKey',9));
 select * into prior from private.quotes where request_key=(p_data->>'requestKey')::uuid;
 if found then if prior.fingerprint<>p_fingerprint then raise exception 'Talep anahtarı farklı içerikle kullanılmış.' using errcode='PT409';end if;return jsonb_build_object('id',prior.id,'duplicate',true);end if;
 if not private.consume_site_limit('quote',p_ip_hash,5) then raise exception 'Çok fazla talep. Bir dakika sonra tekrar deneyin.' using errcode='PT429';end if;
 perform pg_advisory_xact_lock(hashtextextended(email_value||company_value,10));
 select id into customer_id_value from private.customers where lower(email)=email_value and lower(company)=lower(company_value) and deleted_at is null order by created_at limit 1;
 if customer_id_value is null then insert into private.customers(name,company,email,phone) values(customer_name,company_value,email_value,details->>'phone') returning id into customer_id_value;end if;
 insert into private.quotes(request_key,fingerprint,customer,customer_note,customer_id,member_id) values((p_data->>'requestKey')::uuid,p_fingerprint,jsonb_build_object('name',customer_name,'company',company_value,'email',email_value,'phone',details->>'phone'),coalesce(details->>'note',''),customer_id_value,p_member_id) returning id into quote_id;
 for v in select * from jsonb_array_elements(p_data->'items') loop
 if (v->>'qty')::int not between 1 and 1000000 then raise exception 'Ürün adedi geçersiz.' using errcode='22023';end if;
 select * into p from public.products where id=v->>'id' and private.product_is_public(id);if not found then raise exception 'Ürün artık yayında değil; sepeti güncelleyin.' using errcode='22023';end if;
 insert into private.quote_items(quote_id,product_id,snapshot,quantity,position) values(quote_id,p.id,jsonb_build_object('code',p.sku,'name',p.name),(v->>'qty')::int,n);n:=n+1;
 end loop;
 if n=0 then insert into private.quote_items(quote_id,snapshot,quantity) values(quote_id,jsonb_build_object('code','Özel talep','name',details->>'note'),1);end if;
 insert into private.staff_notifications(recipient_id,quote_id) select user_id,quote_id from private.staff_members where active and role in ('admin','sales');
 if coalesce((select (value->>'enabled')::boolean from private.integration_settings where key='quote_notifications'),false) then insert into private.notification_outbox(quote_id) values(quote_id);end if;
 return jsonb_build_object('id',quote_id,'duplicate',false);end $$;
revoke all on function public.submit_site_quote(jsonb,text,text,uuid) from public,anon,authenticated;grant execute on function public.submit_site_quote(jsonb,text,text,uuid) to service_role;

create function public.admin_notification_settings(p_value jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin perform private.require_admin();
 if p_value is not null then if pg_column_size(p_value)>8192 or (p_value->>'recipient')!~'^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then raise exception 'Geçerli bildirim e-postası girin.' using errcode='22023';end if;
 insert into private.integration_settings(key,value) values('quote_notifications',jsonb_build_object('enabled',coalesce((p_value->>'enabled')::boolean,false),'recipient',p_value->>'recipient')) on conflict(key) do update set value=excluded.value;end if;
 select value into result from private.integration_settings where key='quote_notifications';return coalesce(result,'{"enabled":false,"recipient":""}');end $$;
revoke all on function public.admin_notification_settings(jsonb) from public,anon;grant execute on function public.admin_notification_settings(jsonb) to authenticated;
notify pgrst,'reload schema';
